(91882, 'esES', '¡La Alianza ha defendido el aserradero!', '', 19865),
(91883, 'esES', '¡La Horda ha defendido el aserradero!', '', 19865),
(91884, 'esES', '¡La Alianza ha asaltado los establos!', '', 19865),
(91885, 'esES', '¡La Horda ha asaltado los establos!', '', 19865),
(91886, 'esES', '¡La Horda ha defendido los establos!', '', 19865),
